INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('be280f16-c42d-52c5-807e-325d9b518425'::uuid, '15f0bac3-c026-58e6-87b8-48fbb5a06a63'::uuid, 'Hourdis 08', 'Hourdis HO08 en béton 08x20x52 cm, ultra léger, parfait pour les planchers de béton armé nécessitant peu de charge ou des hauteurs réduites.', 'Floor systems (beams & blocks)', NULL, NULL, 4.8, 'MAD', 'Pièce', '1500 Pièce', 'https://lechantier.ma/uploads/media/3edec4148b9d.webp', $j$["https://lechantier.ma/uploads/media/3edec4148b9d.webp", "https://lechantier.ma/uploads/media/57bdfc87dcb3.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/plancher/hourdis-08", "category_fr": "Matériaux de construction", "supplier_matching_status": "partially_matched", "technical_specifications_detailed": "• Type : Corps creux en béton pour planchers de béton arméRéférence produit : HO08Dimensions (cm) : 08 x 20 x 52Utilisation : Idéal pour les planchers légers à faible portée ou les zones nécessitant une hauteur réduite.Matériau : Béton préfabriqué, résistant à la compression, léger et maniable.Avantages : Économie de poids sur la structure porteuse, facilité de pose, réduction de consommation de béton.Compatibilité : Intégration aisée dans les planchers à poutrelles nervurées.Normes : Conforme à la norme marocaine NM 10.1.010 V 1981 pour éléments de plancher béton.", "technical_specifications_original": "• Type : Corps creux en béton pour planchers de béton arméRéférence produit : HO08Dimensions (cm) : 08 x 20 x 52Utilisation : Idéal pour les planchers légers à faible portée ou les zones nécessitant une hauteur réduite.Matériau : Béton préfabriqué, résistant à la compression, léger et maniable.Avantages : Économie de poids sur la structure porteuse, facilité de pose, réduction de consommation de béton.Compatibilité : Intégration aisée dans les planchers à poutrelles nervurées.Normes : Conforme à la norme marocaine NM 10.1.010 V 1981 pour éléments de plancher béton.", "specs": "• Type : Corps creux en béton pour planchers de béton arméRéférence produit : HO08Dimensions (cm) : 08 x 20 x 52Utilisation : Idéal pour les planchers légers à faible portée ou les zones nécessitant une hauteur réduite.Matériau : Béton préfabriqué, résistant à la compression, léger et maniable.Avantages : Économie de poids sur la structure porteuse, facilité de pose, réduction de consommation de béton.Compatibilité : Intégration aisée dans les planchers à poutrelles nervurées.Normes : Conforme à la norme marocaine NM 10.1.010 V 1981 pour éléments de plancher béton."}$j$::jsonb, 'https://lechantier.ma/en/produits/plancher/hourdis-08') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
