INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('2ba305a3-98ab-50e1-8623-431f90f8d574'::uuid, '15f0bac3-c026-58e6-87b8-48fbb5a06a63'::uuid, 'Hourdis 16', 'Hourdis HO16 en béton 16x20x52 cm, léger et robuste, adapté aux planchers de béton armé à faible portée ou avec faible charge.', 'Floor systems (beams & blocks)', NULL, NULL, 6.0, 'MAD', 'Pièce', '940 Pièce', 'https://lechantier.ma/uploads/media/476fd3b1ab63.webp', $j$["https://lechantier.ma/uploads/media/476fd3b1ab63.webp", "https://lechantier.ma/uploads/media/0421fcd81262.webp", "https://lechantier.ma/uploads/media/03ac591d833b.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/plancher/hourdis-16", "category_fr": "Matériaux de construction", "supplier_matching_status": "partially_matched", "technical_specifications_detailed": "• Type : Corps creux en béton pour planchers de béton arméRéférence produit : HO16Dimensions (cm) : 16 x 20 x 52Utilisation : Élément de coffrage perdu pour dalles en béton armé à portée réduite.Matériau : Béton préfabriqué, garantissant solidité et longévité.Avantages : Sa faible hauteur de 16 cm permet une économie de matière et une réduction du poids du plancher.Compatibilité : Convient aux systèmes de planchers nervurés avec poutrelles.Normes : Conforme aux standards de construction pour éléments de plancher en béton armé.", "technical_specifications_original": "• Type : Corps creux en béton pour planchers de béton arméRéférence produit : HO16Dimensions (cm) : 16 x 20 x 52Utilisation : Élément de coffrage perdu pour dalles en béton armé à portée réduite.Matériau : Béton préfabriqué, garantissant solidité et longévité.Avantages : Sa faible hauteur de 16 cm permet une économie de matière et une réduction du poids du plancher.Compatibilité : Convient aux systèmes de planchers nervurés avec poutrelles.Normes : Conforme aux standards de construction pour éléments de plancher en béton armé.", "specs": "• Type : Corps creux en béton pour planchers de béton arméRéférence produit : HO16Dimensions (cm) : 16 x 20 x 52Utilisation : Élément de coffrage perdu pour dalles en béton armé à portée réduite.Matériau : Béton préfabriqué, garantissant solidité et longévité.Avantages : Sa faible hauteur de 16 cm permet une économie de matière et une réduction du poids du plancher.Compatibilité : Convient aux systèmes de planchers nervurés avec poutrelles.Normes : Conforme aux standards de construction pour éléments de plancher en béton armé."}$j$::jsonb, 'https://lechantier.ma/en/produits/plancher/hourdis-16') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
