INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('dd31639b-0042-5690-85f7-5911e9ee9b2d'::uuid, '15f0bac3-c026-58e6-87b8-48fbb5a06a63'::uuid, 'Hourdis 25', 'Hourdis HO25 en béton 25x20x52 cm, robuste et isolant, utilisé pour les planchers de béton armé avec poutrelles préfabriquées.', 'Floor systems (beams & blocks)', NULL, NULL, 8.5, 'MAD', 'Pièce', '620 Pièce', 'https://lechantier.ma/uploads/media/9d9c9285e901.webp', $j$["https://lechantier.ma/uploads/media/9d9c9285e901.webp", "https://lechantier.ma/uploads/media/8e0c0f2ac8e2.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/plancher/hourdis-25-1", "category_fr": "Matériaux de construction", "supplier_matching_status": "partially_matched", "technical_specifications_detailed": "• Type : Corps creux en béton pour planchers de béton arméRéférence produit : HO25Dimensions (cm) : 25 x 20 x 52Utilisation : Élément de coffrage perdu pour planchers à poutrelles, adapté aux portées plus importantes.Matériau : Béton préfabriqué, offrant résistance, rigidité et durabilité.Avantages : Sa hauteur de 25 cm permet d’augmenter la résistance du plancher et d’améliorer l’isolation acoustique.Compatibilité : Conçu pour les systèmes de planchers nervurés béton.Normes : Conforme aux exigences de fabrication pour composants de planchers armés.", "technical_specifications_original": "• Type : Corps creux en béton pour planchers de béton arméRéférence produit : HO25Dimensions (cm) : 25 x 20 x 52Utilisation : Élément de coffrage perdu pour planchers à poutrelles, adapté aux portées plus importantes.Matériau : Béton préfabriqué, offrant résistance, rigidité et durabilité.Avantages : Sa hauteur de 25 cm permet d’augmenter la résistance du plancher et d’améliorer l’isolation acoustique.Compatibilité : Conçu pour les systèmes de planchers nervurés béton.Normes : Conforme aux exigences de fabrication pour composants de planchers armés.", "specs": "• Type : Corps creux en béton pour planchers de béton arméRéférence produit : HO25Dimensions (cm) : 25 x 20 x 52Utilisation : Élément de coffrage perdu pour planchers à poutrelles, adapté aux portées plus importantes.Matériau : Béton préfabriqué, offrant résistance, rigidité et durabilité.Avantages : Sa hauteur de 25 cm permet d’augmenter la résistance du plancher et d’améliorer l’isolation acoustique.Compatibilité : Conçu pour les systèmes de planchers nervurés béton.Normes : Conforme aux exigences de fabrication pour composants de planchers armés."}$j$::jsonb, 'https://lechantier.ma/en/produits/plancher/hourdis-25-1') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
