INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('13845e74-be8e-5878-b761-3ffebf985fe1'::uuid, 'f736cf6b-265a-5f19-9f24-a1c200b9f667'::uuid, 'Mortier de Platre Standard', 'Mortier Projeté STANDARD est un mortier a base de plâtre conçu et formule pour une application par machine de projection sur un support en briques, agglos ou béton.', 'Other', NULL, NULL, 970.0, 'MAD', 'm²', '500 m²', 'https://lechantier.ma/uploads/media/96cb99318d2d.webp', $j$["https://lechantier.ma/uploads/media/96cb99318d2d.webp"]$j$::jsonb, $j$["Safi"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/platre-autres/mortier-de-platre-standard", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• DESCRIPTION ET APPLICATION MORTIER PROJETE STANDARD est un mortier à base de plâtre conçu et formulé pour une application par machine de projection sur un support en briques, agglos ou béton.Ce produit est spécialement conçu pour remplacer le mortier à base de mélange de ciment et de sable et offrir une surface de qualité meilleure avec un gain du temps remarquable. CONSEILS D’UTILISATION\n• Pour une meilleure adhérence du produit sur le support, ce dernier doit être bien nettoyé des poussières.\n• Les surfaces à travailler doivent être planes, il est donc conseillé d’éliminer les éléments saillants et de remplir les creux avant toute utilisation du MORTIER PROJETE STANDARD.\n• MORTIER PROJETE STANDARD est utilisé uniquement pour les travaux intérieurs.\n• La modification du rapport de gâchage eau/ plâtre ou l’utilisation d’une eau sale peuvent dégrader les performances du produit.CARACTERISTIQUES TECHNIQUESNorme 10.7.100 / 10.7.001Rapport de gâchage (Eau/Plâtre). 0.65Durée de cycle d’utilisation. 180 - 220 minEpaisseur conseillée 1-2 cmDureté superficielle (sec) > 60 Shore CDensité apparente 0,8Résistance à l’arrachement > 0.4MPaGranulométrie Refus à 800µm < 0,4%Refus à 100µm < 14%Les caractéristiques techniques ne sont données qu'à titre d'information", "technical_specifications_original": "• DESCRIPTION ET APPLICATION MORTIER PROJETE STANDARD est un mortier à base de plâtre conçu et formulé pour une application par machine de projection sur un support en briques, agglos ou béton.Ce produit est spécialement conçu pour remplacer le mortier à base de mélange de ciment et de sable et offrir une surface de qualité meilleure avec un gain du temps remarquable. CONSEILS D’UTILISATION\n• Pour une meilleure adhérence du produit sur le support, ce dernier doit être bien nettoyé des poussières.\n• Les surfaces à travailler doivent être planes, il est donc conseillé d’éliminer les éléments saillants et de remplir les creux avant toute utilisation du MORTIER PROJETE STANDARD.\n• MORTIER PROJETE STANDARD est utilisé uniquement pour les travaux intérieurs.\n• La modification du rapport de gâchage eau/ plâtre ou l’utilisation d’une eau sale peuvent dégrader les performances du produit.CARACTERISTIQUES TECHNIQUESNorme 10.7.100 / 10.7.001Rapport de gâchage (Eau/Plâtre). 0.65Durée de cycle d’utilisation. 180 - 220 minEpaisseur conseillée 1-2 cmDureté superficielle (sec) > 60 Shore CDensité apparente 0,8Résistance à l’arrachement > 0.4MPaGranulométrie Refus à 800µm < 0,4%Refus à 100µm < 14%Les caractéristiques techniques ne sont données qu'à titre d'information", "specs": "• DESCRIPTION ET APPLICATION MORTIER PROJETE STANDARD est un mortier à base de plâtre conçu et formulé pour une application par machine de projection sur un support en briques, agglos ou béton.Ce produit est spécialement conçu pour remplacer le mortier à base de mélange de ciment et de sable et offrir une surface de qualité meilleure avec un gain du temps remarquable. CONSEILS D’UTILISATION\n• Pour une meilleure adhérence du produit sur le support, ce dernier doit être bien nettoyé des poussières.\n• Les surfaces à travailler doivent être planes, il est donc conseillé d’éliminer les éléments saillants et de remplir les creux avant toute utilisation du MORTIER PROJETE STANDARD.\n• MORTIER PROJETE STANDARD est utilisé uniquement pour les travaux intérieurs.\n• La modification du rapport de gâchage eau/ plâtre ou l’utilisation d’une eau sale peuvent dégrader les performances du produit.CARACTERISTIQUES TECHNIQUESNorme 10.7.100 / 10.7.001Rapport de gâchage (Eau/Plâtre). 0.65Durée de cycle d’utilisation. 180 - 220 minEpaisseur conseillée 1-2 cmDureté superficielle (sec) > 60 Shore CDensité apparente 0,8Résistance à l’arrachement > 0.4MPaGranulométrie Refus à 800µm < 0,4%Refus à 100µm < 14%Les caractéristiques techniques ne sont données qu'à titre d'information"}$j$::jsonb, 'https://lechantier.ma/en/produits/platre-autres/mortier-de-platre-standard') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
