+ ou – 50 poises à 20°CExtrait sec : 70% + ou – 5%Rendement : 3 – 4 m²/kgConservation : 1 an en emballage bien ferméNettoyage & Dilution : EauSECHAGE hors poussière : 1 heureSec : 6 heuresDur : 24 heures"}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-exterieur/caflex-20-kgs') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
