INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('4330a021-7d63-513c-8708-3a8dfab8da75'::uuid, 'a4a38245-1562-5e3b-8e20-be8fdd00b130'::uuid, 'Delta Peinture Sport', 'Delta Peinture Sport – Revêtement de Sol en Caoutchouc Chloré 15L BLANC', 'Exterior coatings', NULL, NULL, 1800.0, 'MAD', 'Litre', '10 m²', 'https://lechantier.ma/uploads/media/0cd8732bea5f.webp', $j$["https://lechantier.ma/uploads/media/0cd8732bea5f.webp"]$j$::jsonb, $j$["Tanger"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-exterieur/delta-peinture-sport", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Peinture au caoutchouc chloré pour la protection des sols intérieurs et des structures métalliques. Offre une excellente résistance chimique aux produits acides et alcalins. Rendement : 8–10 m²/litre Excellent pouvoir couvrant Caractéristiques de Delta pour Sols Produit à base de solvant Application facile Respirant, permet la diffusion de la vapeur d’eau Bonne adhérence par capillarité Grande ténacité et flexibilité, supporte les légères contractions du support Bonne résistance aux huiles minérales Remise en service rapide du sol Comment appliquer cette peinture protectrice ? L’application peut se faire au pinceau, au rouleau ou au pistolet. Ajuster la viscosité selon la méthode d’application et nettoyer les équipements et outils avec EUROSOLV-X. Lorsque le support est préparé et sec, appliquer une première couche de DELTA SPORT CLOROCAUCHO en diluant le produit à 10 % avec EUROSOLV-X. Ensuite, appliquer la deuxième couche avec le produit prêt à l’emploi. Les pourcentages peuvent varier selon les conditions d’application. Bonne lavabilité Très résistante à l’abrasion Séchage rapideMarque : EUROTEX", "technical_specifications_original": "• Peinture au caoutchouc chloré pour la protection des sols intérieurs et des structures métalliques. Offre une excellente résistance chimique aux produits acides et alcalins. Rendement : 8–10 m²/litre Excellent pouvoir couvrant Caractéristiques de Delta pour Sols Produit à base de solvant Application facile Respirant, permet la diffusion de la vapeur d’eau Bonne adhérence par capillarité Grande ténacité et flexibilité, supporte les légères contractions du support Bonne résistance aux huiles minérales Remise en service rapide du sol Comment appliquer cette peinture protectrice ? L’application peut se faire au pinceau, au rouleau ou au pistolet. Ajuster la viscosité selon la méthode d’application et nettoyer les équipements et outils avec EUROSOLV-X. Lorsque le support est préparé et sec, appliquer une première couche de DELTA SPORT CLOROCAUCHO en diluant le produit à 10 % avec EUROSOLV-X. Ensuite, appliquer la deuxième couche avec le produit prêt à l’emploi. Les pourcentages peuvent varier selon les conditions d’application. Bonne lavabilité Très résistante à l’abrasion Séchage rapideMarque : EUROTEX", "specs": "• Peinture au caoutchouc chloré pour la protection des sols intérieurs et des structures métalliques. Offre une excellente résistance chimique aux produits acides et alcalins. Rendement : 8–10 m²/litre Excellent pouvoir couvrant Caractéristiques de Delta pour Sols Produit à base de solvant Application facile Respirant, permet la diffusion de la vapeur d’eau Bonne adhérence par capillarité Grande ténacité et flexibilité, supporte les légères contractions du support Bonne résistance aux huiles minérales Remise en service rapide du sol Comment appliquer cette peinture protectrice ? L’application peut se faire au pinceau, au rouleau ou au pistolet. Ajuster la viscosité selon la méthode d’application et nettoyer les équipements et outils avec EUROSOLV-X. Lorsque le support est préparé et sec, appliquer une première couche de DELTA SPORT CLOROCAUCHO en diluant le produit à 10 % avec EUROSOLV-X. Ensuite, appliquer la deuxième couche avec le produit prêt à l’emploi. Les pourcentages peuvent varier selon les conditions d’application. Bonne lavabilité Très résistante à l’abrasion Séchage rapideMarque : EUROTEX"}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-exterieur/delta-peinture-sport') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
