INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('68b5a89e-a16a-536e-b98f-6ef27af7a57a'::uuid, '7d322a35-dcf1-5dfd-9b6f-55d25b5f1824'::uuid, 'JET ECO 28,5 KGS', 'JET ECO est une peinture mate en phase aqueuse à base d''une résine acrylo-vinylique à grande résistance à l''extérieur pour façade.', 'Exterior coatings', NULL, NULL, 250.0, 'MAD', 'Pièce', '20 Pièce', 'https://lechantier.ma/uploads/media/2a746345ad3a.webp', $j$["https://lechantier.ma/uploads/media/2a746345ad3a.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-exterieur/jet-eco-28-5-kgs", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Aspect : MatDilution : 10% ‘eau courante pour la première couche et 5% pour la deuxième coucheDensité : 1,60 + ou – 0,05 à 20°CViscosité : 140 + ou – 50 poises à 20°CExtrait sec : 65% + ou – 2%Rendement : 5 – 7 m²/kgConservation : 1 an en emballage bien ferméNettoyage & dilution: EauSéchage:Hors poussière : 30 minutesSec : 1 heureDur : 12 heures", "technical_specifications_original": "• Aspect : MatDilution : 10% ‘eau courante pour la première couche et 5% pour la deuxième coucheDensité : 1,60 + ou – 0,05 à 20°CViscosité : 140 + ou – 50 poises à 20°CExtrait sec : 65% + ou – 2%Rendement : 5 – 7 m²/kgConservation : 1 an en emballage bien ferméNettoyage & dilution: EauSéchage:Hors poussière : 30 minutesSec : 1 heureDur : 12 heures", "specs": "• Aspect : MatDilution : 10% ‘eau courante pour la première couche et 5% pour la deuxième coucheDensité : 1,60 + ou – 0,05 à 20°CViscosité : 140 + ou – 50 poises à 20°CExtrait sec : 65% + ou – 2%Rendement : 5 – 7 m²/kgConservation : 1 an en emballage bien ferméNettoyage & dilution: EauSéchage:Hors poussière : 30 minutesSec : 1 heureDur : 12 heures"}$j$::jso