INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('b35b2cc2-0cbb-5418-9284-fa9bea945821'::uuid, '9056c079-eaf5-5665-ab5d-ae5958ddadd3'::uuid, 'Master ACRYSOL Peintures Routière', 'Master Acrysol est un revêtement mat pour traçage au sol, idéal pour routes, passages piétons, flèches, parkings et marquages intérieurs/extérieurs sur divers supports.', 'Exterior coatings', NULL, NULL, 200.0, 'MAD', 'm²', '5 Pièce', 'https://lechantier.ma/uploads/media/b811b9e47960.webp', $j$["https://lechantier.ma/uploads/media/b811b9e47960.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-exterieur/master-acrysol-peintures-routiere", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Caractéristiques – Master AcrysolType : Revêtement de traçage au sol en phase solvantAspect : Mat et lisseApplication : Rouleau, brosse ou machine de marquageUtilisation : Intérieur et extérieurSéchage rapide : Circulation possible en quelques heuresRésistance :Excellente résistance à l’abrasion et aux intempériesRésiste aux hydrocarbures et produits chimiques courantsAdhérence : Très bonne sur béton, asphalte, ciment, etc.Couleurs : Blanc, jaune, rouge, bleu (autres sur demande)Rendement : Environ 2 à 3 m²/L selon l’épaisseur et le supportNettoyage des outils : White spirit ou solvant adapté", "technical_specifications_original": "• Caractéristiques – Master AcrysolType : Revêtement de traçage au sol en phase solvantAspect : Mat et lisseApplication : Rouleau, brosse ou machine de marquageUtilisation : Intérieur et extérieurSéchage rapide : Circulation possible en quelques heuresRésistance :Excellente résistance à l’abrasion et aux intempériesRésiste aux hydrocarbures et produits chimiques courantsAdhérence : Très bonne sur béton, asphalte, ciment, etc.Couleurs : Blanc, jaune, rouge, bleu (autres sur demande)Rendement : Environ 2 à 3 m²/L selon l’épaisseur et le supportNettoyage des outils : White spirit ou solvant adapté", "specs": "• Caractéristiques – Master AcrysolType : Revêtement de traçage au sol en phase solvantAspect : Mat et lisseApplication : Rouleau, brosse ou machine de marquageUtilisation : Intérieur et extérieurSéchage rapide : Circulation possible en quelques heuresRésistance :Excellente résistance à l’abrasion et aux intempériesRésiste aux hydrocarbures et produits chimiques courantsAdhérence : Très bonne sur béton, asphalte, ciment, etc.Couleurs : Blanc, jaune, rouge, bleu (autres sur demande)Rendement : Environ 2 à 3 m²/L selon l’épaisseur et le supportNettoyage des outils : White spirit ou solvant adapté"}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-exterieur/master-acrysol-peintures-routiere') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('fb1f017c-5ef3-588f-86a8-3965d25ada71'::uuid, '9056c079-eaf5-5665-ab5d-ae5958ddadd3'::uuid, 'MASTER FLEX RAPIDE Peinture D''étanchéité', 'Flex Rapide – Peinture d''Étanchéité 5 KG / 20 KG', 'Exterior coatings', NULL, NULL, 120.0, 'MAD', 'm²', '5 Pièce', 'https://lechantier.ma/uploads/media/8b273a70a8a5.webp', $j$["https://lechantier.ma/uploads/media/8b273a70a8a5.webp", "https://lechantier.ma/uploads/media/e9a56f94f1e9.webp", "https://lechantier.ma/uploads/media/e448a42c1801.webp", "https://lechantier.ma/uploads/media/4c4b9a15316d.webp", "https://lechantier.ma/uploads/media/356afb6ab167.webp", "https://lechantier.ma/uploads/media/c75f6d0ac566.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-exterieur/master-flex-rapide-peinture-d-etancheite", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Flex Rapide – Peinture D’étanchéité ÉlastomèreFlex Rapide de Master Sud est une peinture d'étanchéité à base de résines élastomères en phase aqueuse, conçue pour la protection et l’imperméabilisation des surfaces exposées à l’humidité et aux intempéries. Elle forme un film souple, étanche et durable qui résiste aux microfissures et aux variations climatiques.\n• Caractéristiques techniques :Type : Peinture d’étanchéité élastomère en phase aqueuseUtilisation : Extérieur et zones humides (terrasses, toitures, murs, balcons...)Rendement : 1,5 à 2 m²/L par couche selon supportÉlasticité : > 300 % après séchageSéchage :Hors poussière : 1 hRecouvrable : 6 hSéchage complet : 24 à 48 hApplication : Rouleau, pinceau ou airlessNettoyage des outils : Eau🛠️ Avantages :Étanchéité parfaite des supports exposés à l’eauTrès bonne adhérence sur béton, ciment, enduitRésistance aux UV, à l’eau stagnante et aux fissurationsProduit souple et durableFacile à appliquer et sans odeur forte🏠 Domaines d'application :Toitures plates ou inclinéesMurs extérieurs fissurésTerrasses, balcons, souches de cheminéesParois enterrées (avec drainage adéquat)", "technical_specifications_original": "• Flex Rapide – Peinture D’étanchéité ÉlastomèreFlex Rapide de Master Sud est une peinture d'étanchéité à base de résines élastomères en phase aqueuse, conçue pour la protection et l’imperméabilisation des surfaces exposées à l’humidité et aux intempéries. Elle forme un film souple, étanche et durable qui résiste aux microfissures et aux variations climatiques.\n• Caractéristiques techniques :Type : Peinture d’étanchéité élastomère en phase aqueuseUtilisation : Extérieur et zones humides (terrasses, toitures, murs, balcons...)Rendement : 1,5 à 2 m²/L par couche selon supportÉlasticité : > 300 % après séchageSéchage :Hors poussière : 1 hRecouvrable : 6 hSéchage complet : 24 à 48 hApplication : Rouleau, pinceau ou airlessNettoyage des outils : Eau🛠️ Avantages :Étanchéité parfaite des supports exposés à l’eauTrès bonne adhérence sur béton, ciment, enduitRésistance aux UV, à l’eau stagnante et aux fissurationsProduit souple et durableFacile à appliquer et sans odeur forte🏠 Domaines d'application :Toitures plates ou inclinéesMurs extérieurs fissurésTerrasses, balcons, souches de cheminéesParois enterrées (avec drainage adéquat)", "specs": "• Flex Rapide – Peinture D’étanchéité ÉlastomèreFlex Rapide de Master Sud est une peinture d'étanchéité à base de résines élastomères en phase aqueuse, conçue pour la protection et l’imperméabilisation des surfaces exposées à l’humidité et aux intempéries. Elle forme un film souple, étanche et durable qui résiste aux microfissures et aux variations climatiques.\n• Caractéristiques techniques :Type : Peinture d’étanchéité élastomère en phase aqueuseUtilisation : Extérieur et zones humides (terrasses, toitures, murs, balcons...)Rendement : 1,5 à 2 m²/L par couche selon supportÉlasticité : > 300 % après séchageSéchage :Hors poussière : 1 hRecouvrable : 6 hSéchage complet : 24 à 48 hApplication : Rouleau, pinceau ou airlessNettoyage des outils : Eau🛠️ Avantages :Étanchéité parfaite des supports exposés à l’eauTrès bonne adhérence sur béton, ciment, enduitRésistance aux UV, à l’eau stagnante et aux fissurationsProduit souple et durableFacile à appliquer et sans odeur forte🏠 Domaines d'application :Toitures plates ou inclinéesMurs extérieurs fissurésTerrasses, balcons, souches de cheminéesParois enterrées (avec drainage adéquat)"}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-exterieur/master-flex-rapide-peinture-d-etancheite') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
