INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('822c6bcd-dba1-5402-a1ca-96e4d9ae3488'::uuid, 'e23c2fe4-bf47-578b-b12d-ee2397638de0'::uuid, 'Peinture vinylique élite', 'Élite peinture vinylique mate extérieur :', 'Exterior coatings', NULL, NULL, 12.0, 'MAD', 'm²', '100 Kilogramme', 'https://lechantier.ma/uploads/media/2deb2c59348c.webp', $j$["https://lechantier.ma/uploads/media/2deb2c59348c.webp", "https://lechantier.ma/uploads/media/c42cf22cf04b.webp"]$j$::jsonb, $j$["Salé"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-exterieur/peinture-vinylique-elite", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• *Élite : La Peinture Vinylique Mate Extérieure de Haute Qualité*Découvrez Élite, la peinture vinylique mate extérieure de premier choix produite par Afripinte. Conçue pour résister aux conditions climatiques les plus difficiles, Élite offre une protection et une décoration exceptionnelles pour vos surfaces extérieures.*Caractéristiques*- *Résistance aux intempéries* : Élite est formulée pour résister aux rayons UV, à la pluie, au vent et aux températures extrêmes.- *Finition mate* : La finition mate d'Élite offre une apparence élégante et discrète qui convient parfaitement aux surfaces extérieures.- *Durabilité* : Élite est conçue pour durer longtemps, réduisant ainsi les coûts de maintenance et de réparation.- *Facilité d'application* : La peinture Élite est facile à appliquer et sèche rapidement, permettant une mise en œuvre rapide et efficace.*Avantages*- *Protection exceptionnelle* : Élite protège vos surfaces extérieures contre les dommages causés par les intempéries et les UV.- *Esthétique* : La finition mate d'Élite offre une apparence élégante et discrète qui convient parfaitement aux surfaces extérieures.- *Économique* : Élite est conçue pour durer longtemps, réduisant ainsi les coûts de maintenance et de réparation.*Utilisations*- *Murs extérieurs* : Élite est idéale pour les murs extérieurs de bâtiments, de maisons et de structures.- *Façades* : La peinture Élite convient parfaitement aux façades de bâtiments et de structures.- *Surfaces en béton* : Élite peut être utilisée sur les surfaces en béton, les murs en parpaing et les autres surfaces en maçonnerie.*Informations techniques*- *Composition* : Peinture vinylique mate extérieure- *Couleur* : Blanc- *Rendement* : 1 kg couvre jusqu'à 6 mètres carrés- *Séchage* : 6 heures selon la température moyenne*Commandez maintenant*Élite est disponible en blanc. Commandez maintenant et découvrez la qualité et la durabilité de cette peinture vinylique mate extérieure de premier choix.", "technical_specifications_original": "• *Élite : La Peinture Vinylique Mate Extérieure de Haute Qualité*Découvrez Élite, la peinture vinylique mate extérieure de premier choix produite par Afripinte. Conçue pour résister aux conditions climatiques les plus difficiles, Élite offre une protection et une décoration exceptionnelles pour vos surfaces extérieures.*Caractéristiques*- *Résistance aux intempéries* : Élite est formulée pour résister aux rayons UV, à la pluie, au vent et aux températures extrêmes.- *Finition mate* : La finition mate d'Élite offre une apparence élégante et discrète qui convient parfaitement aux surfaces extérieures.- *Durabilité* : Élite est conçue pour durer longtemps, réduisant ainsi les coûts de maintenance et de réparation.- *Facilité d'application* : La peinture Élite est facile à appliquer et sèche rapidement, permettant une mise en œuvre rapide et efficace.*Avantages*- *Protection exceptionnelle* : Élite protège vos surfaces extérieures contre les dommages causés par les intempéries et les UV.- *Esthétique* : La finition mate d'Élite offre une apparence élégante et discrète qui convient parfaitement aux surfaces extérieures.- *Économique* : Élite est conçue pour durer longtemps, réduisant ainsi les coûts de maintenance et de réparation.*Utilisations*- *Murs extérieurs* : Élite est idéale pour les murs extérieurs de bâtiments, de maisons et de structures.- *Façades* : La peinture Élite convient parfaitement aux façades de bâtiments et de structures.- *Surfaces en béton* : Élite peut être utilisée sur les surfaces en béton, les murs en parpaing et les autres surfaces en maçonnerie.*Informations techniques*- *Composition* : Peinture vinylique mate extérieure- *Couleur* : Blanc- *Rendement* : 1 kg couvre jusqu'à 6 mètres carrés- *Séchage* : 6 heures selon la température moyenne*Commandez maintenant*Élite est disponible en blanc. Commandez maintenant et découvrez la qualité et la durabilité de cette peinture vinylique mate extérieure de premier choix.", "specs": "• *Élite : La Peinture Vinylique Mate Extérieure de Haute Qualité*Découvrez Élite, la peinture vinylique mate extérieure de premier choix produite par Afripinte. Conçue pour résister aux conditions climatiques les plus difficiles, Élite offre une protection et une décoration exceptionnelles pour vos surfaces extérieures.*Caractéristiques*- *Résistance aux intempéries* : Élite est formulée pour résister aux rayons UV, à la pluie, au vent et aux températures extrêmes.- *Finition mate* : La finition mate d'Élite offre une apparence élégante et discrète qui convient parfaitement aux surfaces extérieures.- *Durabilité* : Élite est conçue pour durer longtemps, réduisant ainsi les coûts de maintenance et de réparation.- *Facilité d'application* : La peinture Élite est facile à appliquer et sèche rapidement, permettant une mise en œuvre rapide et efficace.*Avantages*- *Protection exceptionnelle* : Élite protège vos surfaces extérieures contre les dommages causés par les intempéries et les UV.- *Esthétique* : La finition mate d'Élite offre une apparence élégante et discrète qui convient parfaitement aux surfaces extérieures.- *É