INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('46f8c563-7c39-5a3e-ae73-8c55dfaeeb33'::uuid, 'a4a38245-1562-5e3b-8e20-be8fdd00b130'::uuid, 'PEINTURE VINYLIQUE - EUROTEX Iriplast', 'PEINTURES VINYLIQUE - EUROTEX Iriplast Inter-Exter Oceon 30KG', 'Exterior coatings', NULL, NULL, 400.0, 'MAD', 'Kilogramme', '1 Kilogramme', 'https://lechantier.ma/uploads/media/89a1e90612f2.webp', $j$["https://lechantier.ma/uploads/media/89a1e90612f2.webp"]$j$::jsonb, $j$["Tanger"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-exterieur/peinture-vinylique-eurotex-iriplast", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• einture vinylique recommandée pour le revêtement décoratif et protecteur des murs et plafonds intérieurs en maçonnerie, constituée d’une émulsion aqueuse de copolymères d’acétate de vinyle-veova, charges, et pigments sélectionnés, par sa bonne qualité elle peut être appliquée aussi à l’extérieur. Le rapport prix-qualité est le principal atout pour cette peinture. - Imperméable à l’eau de pluie. - Très Bon pouvoir couvrant. - Très Bonne blancheur. - Facile homogénéisation et très facile application. - Film à porosité étudiée permettant la respiration du support. - Bonne lavabilité et lessivabilité. - Bonne résistance à l’alcalinité du ciment. - Film résistant aux intempéries et aux rayons ultraviolets. - Bonne résistance à l’abrasion. - Pigments inorganiques résistants au soleileinture vinylique recommandée pour le revêtement décoratif et protecteur des murs et plafonds intérieurs en maçonnerie, constituée d’une émulsion aqueuse de copolymères d’acétate de vinyle-veova, charges, et pigments sélectionnés, par sa bonne qualité elle peut être appliquée aussi à l’extérieur. Le rapport prix-qualité est le principal atout po