INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('ad807df7-3731-5510-ae61-977f57511bfd'::uuid, 'a4a38245-1562-5e3b-8e20-be8fdd00b130'::uuid, 'Anti-Tache Blanc Spray - 400ml Format.', 'Peinture en aérosol blanche mate pour couvrir et sceller durablement les taches tenaces', 'Interior coatings', NULL, NULL, 90.0, 'MAD', 'Litre', '25KG', 'https://lechantier.ma/uploads/media/dc1ded5f89d5.webp', $j$["https://lechantier.ma/uploads/media/dc1ded5f89d5.webp"]$j$::jsonb, $j$["Tanger"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-interieur/anti-tache-blanc-spray-400ml-format", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Peinture en aérosol blanche mate pour couvrir et sceller durablement les taches tenaces sur le béton, le plâtre, les plaques de plâtre, la maçonnerie et les murs et plafonds en bois.Rendement: 0,2 L/m2 (en fonction du substrat)Haute lavabilitéApplication très facileTemps de séchage total: 15 minutesRemise en peinture: 5 minutesCouvre et scelle les taches tenaces avec le spray anti-tachesAvantages :Couverture élevéeBonne rétention des couleursExcellente résistanceAdhésion élevéeNe contient ni plomb ni chromatesNon-jaunissementDurée de vie du produit >3 ans", "technical_specifications_original": "• Peinture en aérosol blanche mate pour couvrir et sceller durablement les taches tenaces sur le béton, le plâtre, les plaques de plâtre, la maçonnerie et les murs et plafonds en bois.Rendement: 0,2 L/m2 (en fonction du substrat)Haute lavabilitéApplication très facileTemps de séchage total: 15 minutesRemise en peinture: 5 minutesCouvre et scelle les taches tenaces avec le spray anti-tachesAvantages :Couverture élevéeBonne rétention des couleursExcellente résistanceAdhésion élevéeNe contient ni plomb ni chromatesNon-jaunissementDurée de vie du produit >3 ans", "specs": "• Peinture en aérosol blanche mate pour couvrir et sceller durablement les taches tenaces sur le béton, le plâtre, les plaques de plâtre, la maçonnerie et les murs et plafonds en bois.Rendement: 0,2 L/m2 (en fonction du substrat)Haute lavabilitéApplication très facileTemps de séchage total: 15 minutesRemise en peinture: 5 minutesCouvre et scelle les taches tenaces avec le spray anti-tachesAvantages :Couverture élevéeBonne rétention des couleursExcellente résistanceAdhésion élevéeNe contient ni plomb ni chromatesNon-jaunissementDurée de vie du produit >3 ans"}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-interieur/anti-tache-blanc-spray-400ml-format') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
