INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('89d225a7-322f-5302-a06d-8e5ef280a4cc'::uuid, 'a4a38245-1562-5e3b-8e20-be8fdd00b130'::uuid, 'Comfortex Thermo 14L – Peinture isolante', 'Pintura aislante térmica y anticondensación de máxima calidad. Comfortex combate los problemas de manchas de humedad por condensación.', 'Interior coatings', NULL, NULL, 999.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/d4d421c5b08a.webp', $j$["https://lechantier.ma/uploads/media/d4d421c5b08a.webp"]$j$::jsonb, $j$["Tanger"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-interieur/comfortex-thermo-14l-peinture-isolante", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Peinture isolante thermique et anti-condensation de haute qualité. Comfortex combat les taches d'humidité causées par la condensation.Convient pour le béton, le ciment, la brique, le fibrociment, etc.Haute durabilitéFinition blanc matParfum agréableTemps de séchage au toucher : 1 heure", "technical_specifications_original": "• Peinture isolante thermique et anti-condensation de haute qualité. Comfortex combat les taches d'humidité causées par la condensation.Convient pour le béton, le ciment, la brique, le fibrociment, etc.Haute durabilitéFinition blanc matParfum agréableTemps de séchage au toucher : 1 heure", "specs": "• Peinture isolante thermique et anti-condensation de haute qualité. Comfortex combat les taches d'humidité causées par la condensation.Convient pour le béton, le ciment, la brique, le fibrociment, etc.Haute durabilitéFinition blanc matParfum agréableTemps de séchage au toucher : 1 heure"}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-interieur/comfortex-thermo-14l-peinture-isolante') ON CONFLICT (id) DO UPDATE SET title = EXC