INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('df74053c-1c58-5a61-ba80-cf15c3d0921c'::uuid, '7d322a35-dcf1-5dfd-9b6f-55d25b5f1824'::uuid, 'CONFORLAC 18.60 KGS', 'CONFORLAC est une peinture laque de finition glycérophtalique brillante à haut extrait sec à base des résines alkydes apporte une protection de tous supports.', 'Interior coatings', NULL, NULL, 630.0, 'MAD', 'Pièce', '20 Pièce', 'https://lechantier.ma/uploads/media/491984015464.webp', $j$["https://lechantier.ma/uploads/media/491984015464.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-interieur/conforlac-18-60-kgs", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Aspect : Brillant, tenduTeinte : BlancDilution : White spiritDensité : 1,20 + ou – 0,01 à 20°CViscosité : 30 + ou – 5 poises à 20°CExtrait sec : 70% + ou – 2%Rendement : 12 – 14 m²/kgConservation : 1 an en emballage bien ferméNon jaunissant à l’applicationSéchage:Hors poussière : 2 heuresSec : 8 heuresDur : 24 heures", "technical_specifications_original": "• Aspect : Brillant, tenduTeinte : BlancDilution : White spiritDensité : 1,20 + ou – 0,01 à 20°CViscosité : 30 + ou – 5 poises à 20°CExtrait sec : 70% + ou – 2%Rendement : 12 – 14 m²/kgConservation : 1 an en emballage bien ferméNon jaunissant à l’applicationSéchage:Hors poussière : 2 heuresSec : 8 heuresDur : 24 heures", "specs": "• Aspect : Brillant, tenduTeinte : BlancDilution : White spiritDensité : 1,20 + ou – 0,01 à 20°CViscosité : 30 + ou – 5 poises à 20°CExtrait sec : 70% + ou – 2%Rendement : 12 – 14 m²/kgConservation : 1 an en emballage bien ferméNon jaunissant à l’applicationSéchage:Hors poussière : 2 heuresSec : 8 heuresDur : 24 heures"}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-interieur/conforlac-18-60-kgs') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('de6542e5-3c80-5dcd-8f96-619cf1efcc04'::uuid, '9056c079-eaf5-5665-ab5d-ae5958ddadd3'::uuid, 'Enduit G15 Pâte 23 KG', 'Enduit G15 est un enduit pâte, très garnissant. Il s''applique sur tous les fonds en ciment, fibrociment, plâtre et bois. Disponible en sac ou seau : 5 kg / 23 kg.', 'Interior coatings', NULL, NULL, 40.0, 'MAD', 'm²', '10 Pièce', 'https://lechantier.ma/uploads/media/12d33a2b56e8.webp', $j$["https://lechantier.ma/uploads/media/12d33a2b56e8.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-interieur/enduit-g15-pate-23-kg", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Caractéristiques techniques – Enduit G15Type : Enduit en pâte prêt à l’emploiAspect : Lisse après séchagePouvoir garnissant : Très élevéSupports compatibles :CimentFibrocimentPlâtreBoisFonctions :Rebouche les aspéritésMasque les irrégularitésProtège contre l’alcalinité des supports cimentésApplication : Spatule, taloche ou lame à enduireFacilité d’application : Très bonneAdhérence : Excellente sur supports absorbantsRendement : Environ 1,5 à 2 kg/m² selon l’épaisseurSéchage : 4 à 6 heures (selon épaisseur et conditions climatiques)Ponçage : Facile une fois secNettoyage des outils : À l’eau", "technical_specifications_original": "• Caractéristiques techniques – Enduit G15Type : Enduit en pâte prêt à l’emploiAspect : Lisse après séchagePouvoir garnissant : Très élevéSupports compatibles :CimentFibrocimentPlâtreBoisFonctions :Rebouche les aspéritésMasque les irrégularitésProtège contre l’alcalinité des supports cimentésApplication : Spatule, taloche ou lame à enduireFacilité d’application : Très bonneAdhérence : Excellente sur supports absorbantsRendement : Environ 1,5 à 2 kg/m² selon l’épaisseurSéchage : 4 à 6 heures (selon épaisseur et conditions climatiques)Ponçage : Facile une fois secNettoyage des outils : À l’eau", "specs": "• Caractéristiques techniques – Enduit G15Type : Enduit en pâte prêt à l’emploiAspect : Lisse après séchagePouvoir garnissant : Très élevéSupports compatibles :CimentFibrocimentPlâtreBoisFonctions :Rebouche les aspéritésMasque les irrégularitésProtège contre l’alcalinité des supports cimentésApplication : Spatule, taloche ou lame à enduireFacilité d’application : Très bonneAdhérence : Excellente sur supports absorbantsRendement : Environ 1,5 à 2 kg/m² selon l’épaisseurSéchage : 4 à 6 heures (selon épaisseur et conditions climatiques)Ponçage : Facile une fois secNettoyage des outils : À l’eau"}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-interieur/enduit-g15-pate-23-kg') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
