INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('57cf8835-78cc-506c-8842-4a68c28af41b'::uuid, '9056c079-eaf5-5665-ab5d-ae5958ddadd3'::uuid, 'LED 300 2eme choix Peinture Vinylique', 'LED 300 – Peinture Intérieure Haut de Gamme Vinylique 2eme Choix 5 Kg / 10Kg / 29 Kg / 45 Kg', 'Interior coatings', NULL, NULL, 100.0, 'MAD', 'm²', '5 Pièce', 'https://lechantier.ma/uploads/media/727f1e3ebf0f.webp', $j$["https://lechantier.ma/uploads/media/727f1e3ebf0f.webp", "https://lechantier.ma/uploads/media/fdadbed1ae38.webp", "https://lechantier.ma/uploads/media/ac0cc62a84c6.webp", "https://lechantier.ma/uploads/media/dcc9c186acdf.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-interieur/led-300-2eme-choix-peinture-vinylique", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• LED 300 – Peinture Intérieure Haut de GammeLED 300 est une peinture décorative de qualité supérieure, conçue pour les murs intérieurs. Elle offre un rendu lisse, une excellente opacité et un fini moderne, tout en étant résistante et facile à entretenir.\n• Caractéristiques techniques :Type : Peinture acrylique en phase aqueuseAspect : Velouté / Satiné (selon version)Rendement : 10 à 12 m²/LSéchage :Sec au toucher : 30 à 45 minRecouvrable : 4 hNettoyage des outils : Eau claireConditionnements : 1L, 5L, 20LCouleurs disponibles : Blanc + nuancier large🛠️ Avantages :Très fort pouvoir couvrantApplication sans traces ni éclaboussuresFini élégant et homogèneBonne lavabilité (résiste aux frottements)Faible odeur et respectueux de l’environnement🏠 Utilisation recommandée :Murs et plafonds intérieursChambres, salons, bureaux, halls…Supports : plâtre, enduit, béton, anciennes peintures mates bien préparées", "technical_specifications_original": "• LED 300 – Peinture Intérieure Haut de GammeLED 300 est une peinture décorative de qualité supérieure, conçue pour les murs intérieurs. Elle offre un rendu lisse, une excellente opacité et un fini moderne, tout en étant résistante et facile à entretenir.\n• Caractéristiques techniques :Type : Peinture acrylique en phase aqueuseAspect : Velouté / Satiné (selon version)Rendement : 10 à 12 m²/LSéchage :Sec au toucher : 30 à 45 minRecouvrable : 4 hNettoyage des outils : Eau claireConditionnements : 1L, 5L, 20LCouleurs disponibles : Blanc + nuancier large🛠️ Avantages :Très fort pouvoir couvrantApplication sans traces ni éclaboussuresFini élégant et homogèneBonne lavabilité (résiste aux frottements)Faible odeur et respectueux de l’environnement🏠 Utilisation recommandée :Murs et plafonds intérieursChambres, salons, bureaux, halls…Supports : plâtre, enduit, béton, anciennes peintures mates bien préparées", "specs": "• LED 300 – Peinture Intérieure Haut de GammeLED 300 est une peinture décorative de qualité supérieure, conçue pour les murs intérieurs. Elle offre un rendu lisse, une excellente opacité et un fini moderne, tout en étant résistante et facile à entretenir.\n• Caractéristiques techniques :Type : Peinture acrylique en phase aqueuseAspect : Velouté / Satiné (selon version)Rendement : 10 à 12 m²/LSéchage :Sec au toucher : 30 à 45 minRecouvrable : 4 hNettoyage des outils : Eau claireConditionnements : 1L, 5L, 20LCouleurs disponibles : Blanc + nuancier large🛠️ Avantages :Très fort pouvoir couvrantApplication sans traces ni éclaboussuresFini élégant et homogèneBonne lavabilité (résiste aux frottements)Faible odeur et respectueux de l’environnement🏠 Utilisation recommandée :Murs et plafonds intérieursChambres, salons, bureaux, halls…Supports : plâtre, enduit, béton, anciennes peintures mates bien préparées"}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-interieur/led-300-2eme-choix-peinture-vinylique') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.