INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('bc17cab1-646d-5833-af31-7c9bdcf1586b'::uuid, '9056c079-eaf5-5665-ab5d-ae5958ddadd3'::uuid, 'Master EPOXY SOL', 'Master Epoxy Sol est une peinture de sol bi-composant à base de résine époxy, idéale pour les surfaces industrielles. Résistante, lisse, brillante et facile à nettoyer.', 'Interior coatings', NULL, NULL, 450.0, 'MAD', 'm²', '5 Pièce', 'https://lechantier.ma/uploads/media/4a6144e3d89e.webp', $j$["https://lechantier.ma/uploads/media/4a6144e3d89e.webp", "https://lechantier.ma/uploads/media/917f27e79353.webp", "https://lechantier.ma/uploads/media/d22353d87c26.webp", "https://lechantier.ma/uploads/media/2986d4338295.webp", "https://lechantier.ma/uploads/media/71e090fe1895.webp", "https://lechantier.ma/uploads/media/1796582ecf33.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-interieur/master-epoxy-sol", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Caractéristiques – Master Epoxy SolType : Peinture de sol bi-composant à base de résine époxyAspect : Lisse, brillant ou satiné selon versionFinition : Durable, résistante à l’abrasion et aux produits chimiquesDestination : Sols intérieurs industriels, parkings, ateliers, entrepôtsRendement : Environ 5 à 7 m²/L selon le supportTemps de séchage :Sec au toucher : 6 à 8 hRecouvrable : 24 hDurcissement complet : 7 joursRésistance :Circulation légère : après 48 hRésistance mécanique et chimique optimale : après polymérisation complèteApplication : Rouleau ou brosse (prévoir primaire si nécessaire)Conditionnement : Kit A + B (ex. 4 L + 1 L durcisseur)Nettoyage des outils : Solvant adapté (ex. diluant époxy)", "technical_specifications_original": "• Caractéristiques – Master Epoxy SolType : Peinture de sol bi-composant à base de résine époxyAspect : Lisse, brillant ou satiné selon versionFinition : Durable, résistante à l’abrasion et aux produits chimiquesDestination : Sols intérieurs industriels, parkings, ateliers, entrepôtsRendement : Environ 5 à 7 m²/L selon le supportTemps de séchage :Sec au toucher : 6 à 8 hRecouvrable : 24 hDurcissement complet : 7 joursRésistance :Circulation légère : après 48 hRésistance mécanique et chimique optimale : après polymérisation complèteApplication : Rouleau ou brosse (prévoir primaire si nécessaire)Conditionnement : Kit A + B (ex. 4 L + 1 L durcisseur)Nettoyage des outils : Solvant adapté (ex. diluant époxy)", "specs": "• Caractéristiques – Master Epoxy SolType : Peinture de sol bi-composant à base de résine époxyAspect : Lisse, brillant ou satiné selon versionFinition : Durable, résistante à l’abrasion et aux produits chimiquesDestination : Sols intérieurs industriels, parkings, ateliers, entrepôtsRendement : Environ 5 à 7 m²/L selon le supportTemps de séchage :Sec au toucher : 6 à 8 hRecouvrable : 24 hDurcissement complet : 7 joursRésistance :Circulation légère : après 48 hRésistance mécanique et chimique optimale : après polymérisation complèteApplication : Rouleau ou brosse (prévoir primaire si nécessaire)Conditionnement : Kit A + B (ex. 4 L + 1 L durcisseur)Nettoyage des outils : Solvant adapté (ex. diluant époxy)"}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-interieur/master-epoxy-sol') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
