INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('f0094033-65ec-571e-abeb-6b9a511cebbc'::uuid, 'a4a38245-1562-5e3b-8e20-be8fdd00b130'::uuid, 'OCEANO F2 REV.LISO AMH BLANCO 14LT', 'Revêtement acrylique lisse avec finition mate pour la protection et la décoration des murs extérieurs et intérieurs.', 'Interior coatings', NULL, NULL, 580.0, 'MAD', 'm²', '1 Kilogramme', 'https://lechantier.ma/uploads/media/37856fc18f16.webp', $j$["https://lechantier.ma/uploads/media/37856fc18f16.webp"]$j$::jsonb, $j$["Tanger"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-interieur/oceano-f2-rev-liso-amh-blanco-14lt", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Il possède un conservateur antimicrobien de dernière génération, offrant une excellente résistance aux taches de moisissure.Garantie : 7 ansClasse d'abrasion : Classe 2Réaction au feu : Certificat BS1D0Pouvoir couvrant : Très élevéBlancheur : ExcellenteRésistance : ÉlevéeRendement approximatif : 16 m²/LPrincipales caractéristiquesImperméable à la pluiePerméable à la vapeur d’eauExcellent pouvoir couvrantBonne résistance à l’alcalinité du supportFilm résistant aux intempéries et aux UVCouleurs claires et résistantes aux conditions climatiquesBonne résistance au frottementFacile à nettoyerEmpêche la formation de moisissures et de mildiouSpécifications techniques – Océan F2Liant : Copolymères acryliquesDiluant : EauCouleur : Blanc et teintes disponibles sur nuancierOpacité : 98 % – Classe 2 (selon UNE-EN 13300) – Rendement : 8 m²/L (pour une couche)Temps de séchage (UNE EN ISO 9117) :Sec au toucher : 30 min à 1hSec en profondeur : 2 hRepeignable : 6 à 8 hIntervalle entre couches (UNE EN ISO 9117) :Minimum : 6 à 12 h à 20°CMaximum : sans limite", "technical_specifications_origina